/**
 * HIRASAKA's own sound, made the way MUJIN's is: its voices and score are files made for it (`lines.ts`, generated by
 * `scripts/hirasaka-audio.mjs`), every one loaded before the run; every effect is synthesised here with Web Audio from
 * one shared noise buffer (the storm, thunder, the waves over the seawall, the cage, the cable, the stone, the gallery
 * telephone, the look-back chime).
 *
 * One take serves many places: the processing is done at play time. `tape` a worn cassette (narrow, hiss, a slow wow),
 * `radio` the boat's handset (narrow, squelch at each end), `pa` the island's horn speakers (narrow, echoing off the
 * concrete), `phone` the gallery telephone, `close` dry at your ear, `far` out in the dark, `monster` pitched down,
 * saturated, darkened. Positioned voices are placed in 3D (HRTF) round the listener.
 *
 * Story lines queue (never two at once) and the score dips under each.
 */
import type { AudioEngineApi } from '../audio/ids';
import { VERSION } from '../version';
import { CUES, LINE, LINES, type Chain } from './lines';

const BASE = './hirasaka/';
/** Lines that wait as long as it takes and go to the front of the queue: Genzō's tapes, the calls. */
const KEEP: ReadonlySet<Chain> = new Set<Chain>(['tape', 'phone']);
type Vec = { x: number; y: number; z: number };

export interface Played {
  id: string;
  dur: number;
}

export class HirasakaSound {
  private ctx: BaseAudioContext | null = null;
  private master: GainNode | null = null;
  private voiceBus: GainNode | null = null;
  private musicBus: GainNode | null = null;
  private sfxBus: GainNode | null = null;
  private verbIn: GainNode | null = null;
  private readonly buffers = new Map<string, AudioBuffer>();
  private readonly reversed = new Map<string, AudioBuffer>();
  private loaded = false;
  private loading: Promise<void> | null = null;
  /** Story lines waiting their turn (never two at once). */
  private queue: { id: string; pos?: Vec; chain?: Chain; at: number; keep: boolean }[] = [];
  private busyUntil = 0;
  private music: { id: string; src: AudioBufferSourceNode; gain: GainNode } | null = null;
  private loops = new Map<string, { stop(fade?: number): void; set?(v: number): void }>();
  /** Two seconds of white noise, shared by every effect (made once, when the graph is). */
  private noiseBuf: AudioBuffer | null = null;
  /** Captions: the game shows whatever is said (`onLine`). */
  onLine: ((id: string) => void) | null = null;
  volume = { voice: 1, music: 0.7, sfx: 0.8 };

  constructor(private readonly audio: AudioEngineApi) {}

  /** Fetch and decode every line and cue (decoding needs no gesture: an offline context does it). */
  load(progress?: (done: number, total: number) => void): Promise<void> {
    if (this.loading) return this.loading;
    const files = [...LINES.map((l) => `voice/${l.id}.mp3`), ...CUES.map((c) => `music/${c.id}.mp3`)];
    let done = 0;
    const off = typeof OfflineAudioContext !== 'undefined' ? new OfflineAudioContext(1, 1, 44100) : null;
    this.loading = (async () => {
      if (!off) return;
      await Promise.all(
        files.map(async (f) => {
          try {
            const r = await fetch(`${BASE}${f}?v=${VERSION}`);
            if (r.ok) {
              const buf = await off.decodeAudioData(await r.arrayBuffer());
              this.buffers.set(f.replace(/^(voice|music)\//, '').replace(/\.mp3$/, ''), buf);
            }
          } catch {
            /* a missing file is a silent line */
          }
          progress?.(++done, files.length);
        }),
      );
      this.loaded = true;
    })();
    return this.loading;
  }

  get ready(): boolean {
    return this.loaded;
  }

  /** Join the game's audio graph (once the engine has its context: after the first click). */
  private graph(): boolean {
    if (this.ctx) return true;
    const ctx = this.audio.context;
    const out = this.audio.input;
    if (!ctx || !out) return false;
    this.ctx = ctx;
    this.master = ctx.createGain();
    this.master.connect(out);
    this.voiceBus = ctx.createGain();
    this.voiceBus.gain.value = this.volume.voice;
    this.voiceBus.connect(this.master);
    this.musicBus = ctx.createGain();
    this.musicBus.gain.value = this.volume.music;
    this.musicBus.connect(this.master);
    this.sfxBus = ctx.createGain();
    this.sfxBus.gain.value = this.volume.sfx;
    this.sfxBus.connect(this.master);
    // a long, dark station reverb (synthesised impulse)
    const len = Math.floor(ctx.sampleRate * 2.6);
    const ir = ctx.createBuffer(2, len, ctx.sampleRate);
    for (let c = 0; c < 2; c++) {
      const d = ir.getChannelData(c);
      for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / len, 3.2);
    }
    const verb = ctx.createConvolver();
    verb.buffer = ir;
    const lp = ctx.createBiquadFilter();
    lp.type = 'lowpass';
    lp.frequency.value = 3200;
    this.verbIn = ctx.createGain();
    this.verbIn.connect(verb).connect(lp).connect(this.master);
    const nb = ctx.createBuffer(1, ctx.sampleRate * 2, ctx.sampleRate);
    const nd = nb.getChannelData(0);
    for (let i = 0; i < nd.length; i++) nd[i] = Math.random() * 2 - 1;
    this.noiseBuf = nb;
    return true;
  }

  // ---------------------------------------------------------------------------------------------
  // voices
  // ---------------------------------------------------------------------------------------------

  /** Say a line now (or as soon as the one before it is done, `story`). Returns its length, 0 if it has no file. */
  say(id: string, o: { pos?: Vec; chain?: Chain; story?: boolean; volume?: number } = {}): number {
    const buf = this.buffers.get(id);
    if (!buf || !this.graph()) return 0;
    const now = this.ctx!.currentTime;
    if (now < this.busyUntil) {
      // a story line waits its turn (a tape or a call at the front, and never dropped); Natsuki's and the crew's asides
      // are not said over one at all
      if (o.story) {
        const keep = KEEP.has(o.chain ?? LINE[id]?.chain ?? 'dry');
        const q = { id, pos: o.pos, chain: o.chain, at: now, keep };
        if (keep) this.queue.splice(this.queue.findIndex((e) => !e.keep) < 0 ? this.queue.length : this.queue.findIndex((e) => !e.keep), 0, q);
        else if (this.queue.length < 4) this.queue.push(q);
        return buf.duration;
      }
      if (/^(sq[fm]_|nat_)/.test(id)) return 0;
    }
    return this.play(id, buf, o.chain ?? LINE[id]?.chain ?? 'dry', o.pos, o.volume ?? 1, !!o.story);
  }

  private play(id: string, buf: AudioBuffer, chain: Chain, pos: Vec | undefined, volume: number, story: boolean): number {
    const ctx = this.ctx!;
    const now = ctx.currentTime;
    const src = ctx.createBufferSource();
    src.buffer = buf;
    let node: AudioNode = src;
    const g = ctx.createGain();
    g.gain.value = volume;
    const band = (lo: number, hi: number): void => {
      const h = ctx.createBiquadFilter();
      h.type = 'highpass';
      h.frequency.value = lo;
      const l = ctx.createBiquadFilter();
      l.type = 'lowpass';
      l.frequency.value = hi;
      node.connect(h).connect(l);
      node = l;
    };
    const grit = (k: number): void => {
      const ws = ctx.createWaveShaper();
      const n = 1024;
      const curve = new Float32Array(n);
      for (let i = 0; i < n; i++) {
        const x = (i / (n - 1)) * 2 - 1;
        curve[i] = Math.tanh(x * k) / Math.tanh(k);
      }
      ws.curve = curve;
      node.connect(ws);
      node = ws;
    };
    let wet = 0.18;
    let dur = buf.duration;
    switch (chain) {
      case 'pa': {
        band(380, 3400);
        grit(2.2);
        wet = 0.6;
        // the far platform's speaker, a beat later
        const d = ctx.createDelay(1);
        d.delayTime.value = 0.27;
        const dg = ctx.createGain();
        dg.gain.value = 0.32;
        node.connect(d).connect(dg).connect(g);
        g.gain.value = volume * 1.15;
        break;
      }
      case 'phone':
        band(520, 2900);
        grit(1.6);
        wet = 0.04;
        g.gain.value = volume * 1.3;
        this.crackle(dur, volume);
        break;
      case 'tape': {
        // a worn cassette: narrow, a little saturated, hiss under it and a slow wow
        band(240, 4600);
        grit(1.3);
        wet = 0.03;
        g.gain.value = volume * 1.2;
        const wow = ctx.createOscillator();
        wow.frequency.value = 0.55;
        const depth = ctx.createGain();
        depth.gain.value = 9;
        wow.connect(depth).connect(src.detune);
        wow.start(now);
        wow.stop(now + dur + 0.2);
        this.hiss(dur + 0.6, 0.018 * volume);
        break;
      }
      case 'radio':
        band(420, 3200);
        grit(2.4);
        wet = 0.02;
        g.gain.value = volume * 1.25;
        this.squelch(now);
        this.squelch(now + dur);
        this.hiss(dur, 0.012 * volume);
        break;
      case 'close':
        wet = 0.06;
        g.gain.value = volume * 1.5;
        break;
      case 'far':
        band(120, 2600);
        wet = 0.7;
        break;
      case 'monster': {
        src.playbackRate.value = 0.8;
        dur = buf.duration / 0.8;
        grit(3);
        const l = ctx.createBiquadFilter();
        l.type = 'lowpass';
        l.frequency.value = 1700;
        node.connect(l);
        node = l;
        wet = 0.55;
        g.gain.value = volume * 1.4;
        break;
      }
      default:
        break;
    }
    node.connect(g);
    let out: AudioNode = g;
    if (pos) {
      const p = ctx.createPanner();
      p.panningModel = 'HRTF';
      p.distanceModel = 'inverse';
      p.refDistance = chain === 'monster' ? 6 : 3;
      p.rolloffFactor = 1.1;
      p.positionX.value = pos.x;
      p.positionY.value = pos.y;
      p.positionZ.value = pos.z;
      g.connect(p);
      out = p;
    }
    out.connect(this.voiceBus!);
    if (wet > 0 && this.verbIn) {
      const s = ctx.createGain();
      s.gain.value = wet;
      out.connect(s).connect(this.verbIn);
    }
    src.start(now);
    if (story) {
      this.busyUntil = now + dur + 0.25;
      this.duck(dur);
    }
    this.onLine?.(id);
    return dur;
  }

  /** The line's crackle down a phone. */
  private crackle(dur: number, volume: number): void {
    this.hiss(dur, 0.02 * volume);
  }

  /** The score dips under a line that matters, then comes back. */
  private duck(dur: number): void {
    const m = this.musicBus;
    if (!m || !this.ctx) return;
    const t = this.ctx.currentTime;
    m.gain.cancelScheduledValues(t);
    m.gain.setTargetAtTime(this.volume.music * 0.35, t, 0.08);
    m.gain.setTargetAtTime(this.volume.music, t + dur + 0.2, 0.5);
  }

  // ---------------------------------------------------------------------------------------------
  // the score
  // ---------------------------------------------------------------------------------------------

  /**
   * Start a cue (crossfading out the one playing). The loop theme comes back changed each loop: `detune` cents,
   * `rate`, and `backwards` once a run (the music_back anomaly).
   */
  cue(id: string, o: { loop?: boolean; fade?: number; detune?: number; rate?: number; backwards?: boolean; volume?: number } = {}): void {
    if (!this.graph()) return;
    let buf = this.buffers.get(id);
    if (!buf) return;
    if (o.backwards) buf = this.reverse(id, buf);
    const ctx = this.ctx!;
    const t = ctx.currentTime;
    const fade = o.fade ?? 1.5;
    this.stopCue(fade);
    const src = ctx.createBufferSource();
    src.buffer = buf;
    src.loop = o.loop ?? false;
    src.detune.value = o.detune ?? 0;
    src.playbackRate.value = o.rate ?? 1;
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.exponentialRampToValueAtTime(o.volume ?? 1, t + fade);
    src.connect(gain).connect(this.musicBus!);
    src.start(t);
    this.music = { id, src, gain };
  }

  stopCue(fade = 1.5): void {
    const m = this.music;
    if (!m || !this.ctx) return;
    const t = this.ctx.currentTime;
    m.gain.gain.cancelScheduledValues(t);
    m.gain.gain.setTargetAtTime(0.0001, t, fade / 3);
    m.src.stop(t + fade + 0.1);
    this.music = null;
  }

  get cueId(): string | null {
    return this.music?.id ?? null;
  }

  private reverse(id: string, buf: AudioBuffer): AudioBuffer {
    let r = this.reversed.get(id);
    if (!r && this.ctx) {
      r = this.ctx.createBuffer(buf.numberOfChannels, buf.length, buf.sampleRate);
      for (let c = 0; c < buf.numberOfChannels; c++) {
        const s = buf.getChannelData(c);
        const d = r.getChannelData(c);
        for (let i = 0; i < s.length; i++) d[i] = s[s.length - 1 - i]!;
      }
      this.reversed.set(id, r);
    }
    return r ?? buf;
  }

  // ---------------------------------------------------------------------------------------------
  // effects (all synthesised)
  // ---------------------------------------------------------------------------------------------

  private tone(freq: number, at: number, dur: number, o: { type?: OscillatorType; vol?: number; pos?: Vec; to?: number; attack?: number } = {}): void {
    const ctx = this.ctx!;
    const osc = ctx.createOscillator();
    osc.type = o.type ?? 'sine';
    osc.frequency.setValueAtTime(freq, at);
    if (o.to) osc.frequency.exponentialRampToValueAtTime(o.to, at + dur);
    const g = ctx.createGain();
    const v = o.vol ?? 0.3;
    g.gain.setValueAtTime(0.0001, at);
    g.gain.exponentialRampToValueAtTime(v, at + (o.attack ?? 0.005));
    g.gain.exponentialRampToValueAtTime(0.0001, at + dur);
    osc.connect(g);
    this.route(g, o.pos, 0.3);
    osc.start(at);
    osc.stop(at + dur + 0.05);
  }

  private noise(at: number, dur: number, o: { lo?: number; hi?: number; vol?: number; pos?: Vec; attack?: number; release?: number; sweep?: number } = {}): void {
    const ctx = this.ctx!;
    if (!this.noiseBuf) return;
    const s = ctx.createBufferSource();
    s.buffer = this.noiseBuf;
    s.loop = true;
    s.loopStart = Math.random();
    const f = ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.frequency.setValueAtTime(o.lo ?? 800, at);
    if (o.sweep) f.frequency.exponentialRampToValueAtTime(o.sweep, at + dur);
    f.Q.value = o.hi ?? 0.7;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, at);
    g.gain.exponentialRampToValueAtTime(o.vol ?? 0.3, at + (o.attack ?? 0.05));
    g.gain.setValueAtTime(o.vol ?? 0.3, at + Math.max(0.06, dur - (o.release ?? 0.3)));
    g.gain.exponentialRampToValueAtTime(0.0001, at + dur);
    s.connect(f).connect(g);
    this.route(g, o.pos, 0.35);
    s.start(at, Math.random() * 1.5);
    s.stop(at + dur + 0.05);
  }

  private route(n: AudioNode, pos: Vec | undefined, wet: number): void {
    const ctx = this.ctx!;
    let out = n;
    if (pos) {
      const p = ctx.createPanner();
      p.panningModel = 'HRTF';
      p.refDistance = 4;
      p.positionX.value = pos.x;
      p.positionY.value = pos.y;
      p.positionZ.value = pos.z;
      n.connect(p);
      out = p;
    }
    out.connect(this.sfxBus!);
    if (this.verbIn && wet > 0) {
      const s = ctx.createGain();
      s.gain.value = wet;
      out.connect(s).connect(this.verbIn);
    }
  }

  /** Hiss under a tape or a handset. */
  private hiss(dur: number, vol: number): void {
    const ctx = this.ctx!;
    if (!this.noiseBuf) return;
    const s = ctx.createBufferSource();
    s.buffer = this.noiseBuf;
    s.loop = true;
    const f = ctx.createBiquadFilter();
    f.type = 'highpass';
    f.frequency.value = 3000;
    const g = ctx.createGain();
    g.gain.value = vol;
    s.connect(f).connect(g).connect(this.voiceBus!);
    s.start();
    s.stop(ctx.currentTime + dur);
  }

  /** The handset's squelch at the start and end of a call. */
  private squelch(at: number): void {
    this.noise(at, 0.12, { lo: 2200, hi: 1.2, vol: 0.12, attack: 0.005, release: 0.06 });
  }

  /** Thunder: a crack, then the long roll (closer is louder and sooner). */
  thunder(near: number): void {
    if (!this.graph()) return;
    const t = this.ctx!.currentTime + (1 - near) * 1.2;
    this.noise(t, 0.25, { lo: 1800, hi: 0.6, vol: 0.25 * near, attack: 0.004, release: 0.2 });
    this.noise(t + 0.1, 4.5, { lo: 120, sweep: 60, hi: 0.5, vol: 0.5 * (0.4 + near * 0.6), attack: 0.3, release: 3 });
    this.tone(42, t + 0.1, 3, { vol: 0.3 * near, to: 30, attack: 0.2 });
  }

  /** A wave breaking over the seawall: the build, the crash, the wash back. */
  wave(pos: Vec): void {
    if (!this.graph()) return;
    const t = this.ctx!.currentTime;
    this.noise(t, 1.6, { lo: 300, sweep: 900, vol: 0.25, attack: 1.4, release: 0.1, pos });
    this.noise(t + 1.5, 2.6, { lo: 700, sweep: 220, hi: 0.4, vol: 0.7, attack: 0.02, release: 2.2, pos });
    this.tone(55, t + 1.5, 1.4, { vol: 0.35, to: 35, attack: 0.01, pos });
  }

  /** The shaft's signal bell: rapping out the cage's signal (`n` strokes). */
  signal(pos: Vec, n = 3): void {
    if (!this.graph()) return;
    const t = this.ctx!.currentTime;
    for (let k = 0; k < n; k++) for (const [f, v] of [[880, 0.16], [1760, 0.05], [2640, 0.03]] as const) this.tone(f, t + k * 0.45, 0.8, { vol: v, pos });
  }

  /** The cage going down: the brake off, the cable singing, the rush of the shaft, the bump at the bottom. */
  cage(secs: number): void {
    if (!this.graph()) return;
    const t = this.ctx!.currentTime;
    this.noise(t, 0.3, { lo: 2600, hi: 3, vol: 0.3, attack: 0.002, release: 0.2 });
    this.noise(t + 0.2, secs, { lo: 260, sweep: 120, vol: 0.45, attack: 0.6, release: 0.6 });
    this.tone(320, t + 0.2, secs, { vol: 0.05, type: 'sawtooth', to: 140, attack: 0.5 });
    this.noise(t + secs, 0.5, { lo: 140, hi: 0.8, vol: 0.6, attack: 0.005, release: 0.4 });
    this.tone(48, t + secs, 0.6, { vol: 0.5, to: 30, attack: 0.005 });
  }

  /** The cable parting far up the shaft, and the cage coming down it. */
  cable(pos: Vec): void {
    if (!this.graph()) return;
    const t = this.ctx!.currentTime;
    this.noise(t, 0.4, { lo: 3200, hi: 4, vol: 0.5, attack: 0.002, release: 0.3, pos });
    this.tone(1900, t, 1.6, { vol: 0.12, type: 'sawtooth', to: 260, pos });
    this.noise(t + 1.6, 3, { lo: 180, sweep: 60, hi: 0.5, vol: 0.9, attack: 0.01, release: 2.6, pos });
    this.tone(36, t + 1.6, 2.4, { vol: 0.6, to: 24, attack: 0.01 });
  }

  /** The stone grinding in its groove (one push's worth, about a second). */
  grind(pos: Vec, level: number): void {
    if (!this.graph()) return;
    const t = this.ctx!.currentTime;
    this.noise(t, 1.1, { lo: 90, hi: 0.9, vol: 0.4 * level, attack: 0.2, release: 0.5, pos });
    this.tone(38, t, 1.1, { vol: 0.25 * level, attack: 0.2, pos });
  }

  /** The stone dropping home: the boom that ends it. */
  seal(pos: Vec): void {
    if (!this.graph()) return;
    const t = this.ctx!.currentTime;
    this.noise(t, 3.5, { lo: 80, sweep: 40, hi: 0.6, vol: 1, attack: 0.005, release: 3, pos });
    this.tone(30, t, 3, { vol: 0.8, to: 22, attack: 0.005 });
    for (const [f, v] of [[220, 0.1], [330, 0.06], [440, 0.04]] as const) this.tone(f, t + 0.4, 4, { vol: v, type: 'sine' });
  }

  /** The gallery telephone ringing (an old bell ringer). */
  ring(pos: Vec): void {
    if (!this.graph()) return;
    const t = this.ctx!.currentTime;
    for (let k = 0; k < 2; k++) for (let i = 0; i < 22; i++) this.tone(i % 2 ? 1300 : 1050, t + k * 0.6 + i * 0.02, 0.025, { vol: 0.09, pos, type: 'square' });
  }

  /** The chime when you look back at her: a struck glass, falling. */
  chime(): void {
    if (!this.graph()) return;
    const t = this.ctx!.currentTime;
    this.tone(1568, t, 1.6, { vol: 0.16, to: 1480 });
    this.tone(2349, t + 0.04, 1.2, { vol: 0.08, to: 2200 });
    this.tone(784, t, 2.2, { vol: 0.06 });
  }

  /** A peach bursting into its ward: a soft chord and a shimmer. */
  peach(pos: Vec): void {
    if (!this.graph()) return;
    const t = this.ctx!.currentTime;
    [523, 659, 784, 1047].forEach((f, i) => this.tone(f, t + i * 0.05, 2.6, { vol: 0.07, pos, type: 'triangle' }));
    this.noise(t, 1.2, { lo: 6000, hi: 2, vol: 0.06, attack: 0.05, release: 1, pos });
  }

  /** A pickup (a tape, a photograph, the key): a small clean click. */
  pick(): void {
    if (!this.graph()) return;
    const t = this.ctx!.currentTime;
    this.tone(1320, t, 0.12, { vol: 0.12, type: 'triangle' });
    this.tone(1980, t + 0.06, 0.18, { vol: 0.08, type: 'triangle' });
  }

  /** The island's evening chime from the horn speakers (before an announcement). */
  speaker(pos?: Vec): void {
    if (!this.graph()) return;
    const t = this.ctx!.currentTime;
    [523, 587, 659, 784, 659].forEach((f, i) => this.tone(f, t + i * 0.45, 1, { vol: 0.12, pos, type: 'triangle' }));
  }

  /** The storm: wind and rain, a loop whose level follows `level` (0 in the mine, 1 on the island, more in the surge). */
  storm(level: number): void {
    if (!this.graph() || !this.noiseBuf) return;
    let l = this.loops.get('storm');
    if (!l) {
      const ctx = this.ctx!;
      const mk = (lo: number, q: number, rate: number): { g: GainNode; s: AudioBufferSourceNode } => {
        const s = ctx.createBufferSource();
        s.buffer = this.noiseBuf;
        s.loop = true;
        s.playbackRate.value = rate;
        const f = ctx.createBiquadFilter();
        f.type = 'bandpass';
        f.frequency.value = lo;
        f.Q.value = q;
        const g = ctx.createGain();
        g.gain.value = 0;
        s.connect(f).connect(g).connect(this.sfxBus!);
        s.start();
        return { g, s };
      };
      const rain = mk(3800, 0.4, 1);
      const wind = mk(420, 1.6, 0.6);
      // the wind gusts: a slow wobble on its level
      const lfo = ctx.createOscillator();
      lfo.frequency.value = 0.09;
      const lg = ctx.createGain();
      lg.gain.value = 0.05;
      lfo.connect(lg).connect(wind.g.gain);
      lfo.start();
      l = {
        stop: () => {
          rain.s.stop();
          wind.s.stop();
          lfo.stop();
        },
        set: (v: number) => {
          rain.g.gain.setTargetAtTime(v * 0.1, ctx.currentTime, 0.6);
          wind.g.gain.setTargetAtTime(v * 0.08, ctx.currentTime, 0.6);
        },
      };
      this.loops.set('storm', l);
    }
    l.set?.(level);
  }

  /** A held tone (the White Shape while you look at it): `level` 0..1. */
  hold(id: string, level: number, freq: number): void {
    if (!this.graph()) return;
    let l = this.loops.get(id);
    if (!l && level > 0.01) {
      const ctx = this.ctx!;
      const osc = ctx.createOscillator();
      osc.type = 'sine';
      osc.frequency.value = freq;
      const o2 = ctx.createOscillator();
      o2.frequency.value = freq * 1.007;
      const g = ctx.createGain();
      g.gain.value = 0;
      osc.connect(g);
      o2.connect(g);
      g.connect(this.sfxBus!);
      osc.start();
      o2.start();
      l = {
        stop: () => {
          osc.stop();
          o2.stop();
        },
        set: (v: number) => g.gain.setTargetAtTime(v * 0.12, ctx.currentTime, 0.1),
      };
      this.loops.set(id, l);
    }
    l?.set?.(level);
  }

  /** Follow the listener (positional sound, HRTF). */
  update(): void {
    const ctx = this.ctx;
    const li = this.audio.listener;
    if (!ctx || !li) return;
    const L = ctx.listener;
    if (L.positionX) {
      L.positionX.value = li.x;
      L.positionY.value = li.y;
      L.positionZ.value = li.z;
      L.forwardX.value = li.fx;
      L.forwardY.value = 0;
      L.forwardZ.value = li.fz;
      L.upX.value = 0;
      L.upY.value = 1;
      L.upZ.value = 0;
    }
    if (this.queue.length > 0 && ctx.currentTime >= this.busyUntil) {
      const q = this.queue.shift()!;
      // a line that waited too long has missed its moment
      if (q.keep || ctx.currentTime - q.at < 8) this.say(q.id, { pos: q.pos, chain: q.chain, story: true });
    }
  }

  /** Everything quiet (a new run, the results). */
  stopAll(fade = 0.6): void {
    this.stopCue(fade);
    for (const l of this.loops.values()) l.stop();
    this.loops.clear();
    this.queue.length = 0;
    this.busyUntil = 0;
  }
}
